using System;
using System.Collections.Generic;
using System.Linq;
readonly record struct Position(string File, int Line) {
    public override string ToString() => $"{File}:{Line}";
}
sealed record Diagnostic(Position Position, string Kind, string Message);
sealed class PPError(string reason) : Exception(reason) {
    public string Reason {
        get;
    } = reason;
}
sealed class Macro(string name, List<string>? parameters, bool variadic, List<Token> replacement, Position position, bool main) {
    public string Name {
        get;
    } = name;
    public List<string>? Parameters {
        get;
    } = parameters;
    public bool Variadic {
        get;
    } = variadic;
    public List<Token> Replacement {
        get;
    } = replacement;
    public Position Position {
        get;
    } = position;
    public bool Main {
        get;
    } = main;
    public int Expanded {
        get;
        set;
    } public int Tested {
        get;
        set;
    }
    public string Signature => Parameters == null ? Name : Name + "(" + string.Join(", ", Parameters.Select((parameter, i) => Variadic && i == Parameters.Count - 1 ? "..." : parameter)) + ")";
    public string Definition => "#define " + Signature + (Replacement.Count == 0 ? "" : " " + Lexer.Render(Replacement));
    public bool Identical(Macro other) => (Parameters == null ? other.Parameters == null : other.Parameters != null && Parameters.SequenceEqual(other.Parameters)) && Variadic == other.Variadic && Replacement.Count == other.Replacement.Count && Replacement.Zip(other.Replacement).All(pair => pair.First.Text == pair.Second.Text && pair.First.Space == pair.Second.Space);
}
static class Definitions {
    public static bool Builtin(string name) => name is "__LINE__" or "__FILE__" or "__COUNTER__";
    public static string Name(List<Token> tokens, string directive) {
        if (tokens.Count == 0) throw new PPError($"no macro name given in #{directive} directive");
        Token token = tokens[0];
        if (token.Kind != "identifier") throw new PPError("macro names must be identifiers");
        if (token.Text == "defined") throw new PPError("\"defined\" cannot be used as a macro name");
        if (Builtin(token.Text)) throw new PPError($"cannot {(directive == "define" ? "redefine" : "undefine")} builtin macro \"{token.Text}\"");
        return token.Text;
    }
    public static Macro Parse(List<Token> tokens, Position position, bool main) {
        string name = Name(tokens, "define"), vaError = "\"__VA_ARGS__\" can only appear in the expansion of a variadic macro";
        if (name == "__VA_ARGS__") throw new PPError(vaError);
        int i = 1;
        List<string>? parameters = null;
        bool variadic = false;
        if (tokens.Count > 1 && tokens[1].Text == "(" && !tokens[1].Space) {
            i = 2;
            List<string> names = new();
            if (i < tokens.Count && tokens[i].Text == ")") i++;
            else while (true) {
                if (i == tokens.Count) throw new PPError("missing ')' in macro parameter list");
                Token token = tokens[i];
                if (token.Text == "...") {
                    variadic = true;
                    names.Add("__VA_ARGS__");
                }
                else if (token.Kind == "identifier") {
                    if (token.Text == "__VA_ARGS__") throw new PPError(vaError);
                    if (names.Contains(token.Text)) throw new PPError($"duplicate macro parameter \"{token.Text}\"");
                    names.Add(token.Text);
                }
                else throw new PPError($"expected parameter name, found \"{token.Text}\"");
                i++;
                if (i == tokens.Count) throw new PPError("missing ')' in macro parameter list");
                if (tokens[i].Text == ")") {
                    i++;
                    break;
                } if (variadic) throw new PPError($"expected ')' after \"...\", found \"{tokens[i].Text}\"");
                if (tokens[i].Text != ",") throw new PPError($"expected ',' or ')', found \"{tokens[i].Text}\"");
                i++;
            }
            parameters = names;
        }
        List<Token> replacement = tokens.Skip(i).Select((token, k) => k == 0 ? token with {
            Space = false
        } : token).ToList();
        if (replacement.FirstOrDefault()?.Text == "##" || replacement.LastOrDefault()?.Text == "##") throw new PPError("'##' cannot appear at either end of a macro expansion");
        for (int k = 0; k < replacement.Count; k++) {
            Token token = replacement[k];
            if (token.Kind == "identifier" && token.Text == "__VA_ARGS__" && !variadic) throw new PPError(vaError);
            if (token.Text == "#" && parameters != null && (k + 1 == replacement.Count || replacement[k + 1].Kind != "identifier" || !parameters.Contains(replacement[k + 1].Text))) throw new PPError("'#' is not followed by a macro parameter");
        } return new(name, parameters, variadic, replacement, position, main);
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
abstract record ReplacementItem {
    public sealed record Sequence(List<Token> Tokens) : ReplacementItem;
    public sealed record Paste(Token Token) : ReplacementItem;
}
sealed record Collected(List<List<Token>> Arguments, int Consumed, Token Closing);
sealed class Expander {
    public Dictionary<string, Macro> Table {
        get;
    } = new();
    public List<Diagnostic> Diagnostics {
        get;
    } = new();
    public Dictionary<string, int> Uses {
        get;
    } = new() {
        ["__COUNTER__"] = 0, ["__FILE__"] = 0, ["__LINE__"] = 0
    };
    int counter;
    public void Diagnostic(Position position, string kind, string message) => Diagnostics.Add(new(position, kind, message));
    void Error(Token token, string file, int offset, string message) => Diagnostic(new(file, token.Line + offset), "error", message);
    public List<Token> Expand(List<Token> tokens, string file, int offset) {
        List<Token> input = tokens.AsEnumerable().Reverse().ToList(), result = new();
        while (input.Count > 0) {
            Token token = input[^1];
            input.RemoveAt(input.Count - 1);
            if (token.Kind != "identifier" || token.Hide.Contains(token.Text)) {
                result.Add(token);
                continue;
            }
            if (Definitions.Builtin(token.Text)) {
                Uses[token.Text]++;
                string kind, text;
                switch (token.Text) {
                    case "__LINE__": kind = "number";
                    text = (token.Line + offset).ToString();
                    break;
                    case "__FILE__": kind = "string";
                    text = "\"" + file + "\"";
                    break;
                    default: kind = "number";
                    text = counter.ToString();
                    counter++;
                    break;
                } result.Add(new(kind, text, token.Line, token.Space));
                continue;
            }
            if (!Table.TryGetValue(token.Text, out Macro? definition)) {
                result.Add(token);
                continue;
            } HashSet<string> hide = new(token.Hide);
            List<List<Token>> arguments = new();
            if (definition.Parameters != null) {
                if (input.LastOrDefault()?.Text != "(") {
                    result.Add(token);
                    continue;
                } Collected? collected = Collect(definition, input, token, file, offset);
                if (collected == null) {
                    result.Add(token);
                    continue;
                } arguments = collected.Arguments;
                input.RemoveRange(input.Count - collected.Consumed, collected.Consumed);
                hide.IntersectWith(collected.Closing.Hide);
            }
            hide.Add(definition.Name);
            List<Token> replacement = Substitute(definition, arguments, token, hide, file, offset);
            definition.Expanded++;
            if (replacement.Count == 0 && token.Space && input.Count > 0) input[^1] = input[^1] with {
                Space = true
            };
            input.AddRange(replacement.AsEnumerable().Reverse());
        }
        return result;
    }
    Collected? Collect(Macro definition, List<Token> reversed, Token token, string file, int offset) {
        List<List<Token>> arguments = new() {
            new()
        };
        List<Token> separators = new();
        int depth = 0;
        (int Index, Token Token)? closing = null;
        List<Token> input = reversed.AsEnumerable().Reverse().ToList();
        for (int i = 1; i < input.Count; i++) {
            Token current = input[i];
            if (current.Text == ")" && depth == 0) {
                closing = (i, current);
                break;
            } if (current.Text == "," && depth == 0) {
                separators.Add(current);
                arguments.Add(new());
            } else {
                if (current.Text == "(") depth++;
                else if (current.Text == ")") depth--;
                arguments[^1].Add(current);
            }
        }
        if (closing == null) {
            Error(token, file, offset, $"unterminated argument list invoking macro \"{definition.Name}\"");
            return null;
        }
        int k = arguments.Count, n = definition.Parameters!.Count - (definition.Variadic ? 1 : 0);
        bool emptyZero = !definition.Variadic && n == 0 && k == 1 && arguments[0].Count == 0;
        string? message = !definition.Variadic && n == 0 && !emptyZero ? $"macro \"{definition.Name}\" passed {k} arguments, but takes just 0" : k < n ? $"macro \"{definition.Name}\" requires {n} arguments, but only {k} given" : k > n && !definition.Variadic ? $"macro \"{definition.Name}\" passed {k} arguments, but takes just {n}" : null;
        if (message != null) {
            Error(token, file, offset, message);
            return null;
        }
        if (definition.Variadic) {
            List<Token> variable = new();
            for (int i = n; i < k; i++) {
                if (i > n) variable.Add(separators[i - 1]);
                variable.AddRange(arguments[i]);
            } arguments = arguments.Take(n).ToList();
            arguments.Add(variable);
        } else if (emptyZero) arguments = new();
        return new(arguments, closing.Value.Index + 1, closing.Value.Token);
    }
    static Token Stringize(List<Token> tokens, Token template) {
        StringBuilder text = new();
        for (int i = 0; i < tokens.Count; i++) {
            Token token = tokens[i];
            if (i > 0 && token.Space) text.Append(' ');
            if (token.Kind is "string" or "character") {
                foreach (char c in token.Text) {
                    if (c is (char)92 or '"') text.Append((char)92);
                    text.Append(c);
                }
            } else text.Append(token.Text);
        } return new("string", "\"" + text + "\"", template.Line, template.Space);
    }
    List<Token> Paste(Token left, Token right, Token invocation, string file, int offset) {
        if (left.Kind == "placemarker") return new() {
            right with {
                Space = left.Space
            }
        };
        if (right.Kind == "placemarker") return new() {
            left
        };
        string text = left.Text + right.Text;
        string? kind = Lexer.Single(text);
        if (kind != null) return new() {
            new(kind, text, left.Line, left.Space, left.Hide.Intersect(right.Hide).ToHashSet())
        };
        Error(invocation, file, offset, $"pasting \"{left.Text}\" and \"{right.Text}\" does not give a valid preprocessing token");
        return new() {
            left, right with {
                Space = false
            }
        };
    }
    List<Token> Substitute(Macro definition, List<List<Token>> arguments, Token invocation, HashSet<string> hide, string file, int offset) {
        List<string> names = definition.Parameters ?? new();
        List<Token> replacement = definition.Replacement;
        Dictionary<int, List<Token>> expanded = new();
        List<ReplacementItem> items = new();
        int i = 0;
        while (i < replacement.Count) {
            Token token = replacement[i];
            if (token.Text == "#" && definition.Parameters != null) {
                int parameter = names.IndexOf(replacement[i + 1].Text);
                items.Add(new ReplacementItem.Sequence(new() {
                    Stringize(arguments[parameter], token)
                }));
                i += 2;
                continue;
            }
            if (token.Text == "##") items.Add(new ReplacementItem.Paste(token));
            else if (token.Kind == "identifier" && names.Contains(token.Text)) {
                int parameter = names.IndexOf(token.Text);
                bool raw = i > 0 && replacement[i - 1].Text == "##" || i + 1 < replacement.Count && replacement[i + 1].Text == "##";
                List<Token> sequence;
                if (raw) sequence = arguments[parameter];
                else {
                    if (!expanded.TryGetValue(parameter, out sequence!)) {
                        sequence = Expand(arguments[parameter], file, offset);
                        expanded[parameter] = sequence;
                    }
                } items.Add(new ReplacementItem.Sequence(sequence.Count == 0 ? new() {
                    new("placemarker", "", token.Line, token.Space)
                } : sequence.Select((value, k) => k == 0 ? value with {
                    Space = token.Space
                } : value).ToList()));
            }
            else items.Add(new ReplacementItem.Sequence(new() {
                token
            }));
            i++;
        }
        List<Token> output = new();
        i = 0;
        while (i < items.Count) {
            switch (items[i]) {
                case ReplacementItem.Sequence sequence: output.AddRange(sequence.Tokens);
                break;
                case ReplacementItem.Paste: {
                    Token left = output[^1];
                    output.RemoveAt(output.Count - 1);
                    List<Token> right = items[i + 1] switch {
                        ReplacementItem.Sequence rightSequence => rightSequence.Tokens, ReplacementItem.Paste paste => new() {
                            paste.Token
                        }, _ => throw new InvalidOperationException()
                    };
                    output.AddRange(Paste(left, right[0], invocation, file, offset));
                    output.AddRange(right.Skip(1));
                    i++;
                    break;
                }
            } i++;
        }
        List<Token> result = new();
        bool space = false;
        foreach (Token token in output) {
            if (token.Kind == "placemarker") {
                space |= token.Space;
                continue;
            } result.Add(token with {
                Line = invocation.Line, Space = token.Space || space, Hide = token.Hide.Union(hide).ToHashSet()
            });
            space = false;
        } if (result.Count > 0) result[0] = result[0] with {
            Space = invocation.Space
        };
        return result;
    }
}

using System;
using System.Collections.Generic;
using System.Globalization;
using System.Linq;
abstract record PPExpression {
    public sealed record Value(long Number) : PPExpression;
    public sealed record Name(string Text) : PPExpression;
    public sealed record Unary(string Op, PPExpression Operand) : PPExpression;
    public sealed record Binary(string Op, PPExpression Left, PPExpression Right) : PPExpression;
    public sealed record Conditional(PPExpression Condition, PPExpression Yes, PPExpression No) : PPExpression;
}
sealed class ExpressionParser(List<Token> tokens) {
    public int Index {
        get;
        private set;
    }
    string Text => Index < tokens.Count ? tokens[Index].Text : "";
    static int Priority(string op) => op switch {
        "||" => 1, "&&" => 2, "|" => 3, "^" => 4, "&" => 5, "==" or "!=" => 6, "<" or ">" or "<=" or ">=" => 7, "<<" or ">>" => 8, "+" or "-" => 9, "*" or "/" or "%" => 10, _ => 0
    };
    PPExpression Expression() {
        PPExpression left = Binary(1);
        if (Text != "?") return left;
        Index++;
        PPExpression yes = Expression();
        if (Text != ":") throw new PPError("'?' without following ':'");
        Index++;
        return new PPExpression.Conditional(left, yes, Expression());
    }
    PPExpression Binary(int minimum) {
        PPExpression left = Unary();
        while (Priority(Text) >= minimum) {
            string op = Text;
            Index++;
            left = new PPExpression.Binary(op, left, Binary(Priority(op) + 1));
        } return left;
    }
    PPExpression Unary() {
        if (Text is "+" or "-" or "!" or "~") {
            string op = Text;
            Index++;
            return new PPExpression.Unary(op, Unary());
        } if (Index == tokens.Count) throw new PPError("expected value at end of expression");
        Token token = tokens[Index++];
        if (token.Kind is "number" or "character") return new PPExpression.Value(Constant(token));
        if (token.Kind == "identifier") return new PPExpression.Name(token.Text);
        if (token.Text == "(") {
            PPExpression value = Expression();
            if (Text != ")") throw new PPError("missing ')' in expression");
            Index++;
            return value;
        } throw new PPError($"expected value before \"{token.Text}\"");
    }
    static long Constant(Token token) {
        string original = token.Text;
        if (token.Kind == "character") {
            string body = original[1..^1];
            if (body.Length == 1 && body[0] != 39 && body[0] != 92) return body[0];
            Dictionary<char, long> escapes = new() {
                ['n'] = 10, ['t'] = 9, [(char)92] = 92, [(char)39] = 39, ['"'] = 34, ['0'] = 0
            };
            if (body.Length == 2 && body[0] == 92 && escapes.TryGetValue(body[1], out long value)) return value;
            throw new PPError("invalid character constant " + original);
        }
        string number = original;
        foreach (string suffix in new[] {
            "ll", "LL", "l", "L"
        }) if (number.Length > suffix.Length && number.EndsWith(suffix, StringComparison.Ordinal)) {
            number = number[..^suffix.Length];
            break;
        } int radix;
        string digits;
        if (number.StartsWith("0x", StringComparison.Ordinal) || number.StartsWith("0X", StringComparison.Ordinal)) {
            radix = 16;
            digits = number[2..];
        } else if (number.StartsWith('0')) {
            radix = 8;
            digits = number;
        } else {
            radix = 10;
            digits = number;
        }
        bool valid = digits.Length > 0 && digits.All(c => radix == 16 ? c is >= '0' and <= '9' or >= 'a' and <= 'f' or >= 'A' and <= 'F' : radix == 8 ? c is >= '0' and <= '7' : c is >= '0' and <= '9');
        if (valid) {
            long value = 0;
            foreach (char c in digits) value = value * radix + (c <= '9' ? c - '0' : char.ToLowerInvariant(c) - 'a' + 10);
            return value;
        } throw new PPError($"invalid integer constant \"{original}\"");
    }
    static long Evaluate(PPExpression expression, List<(string Kind, string Message)> diagnostics) {
        switch (expression) {
            case PPExpression.Value value: return value.Number;
            case PPExpression.Name name: diagnostics.Add(("warning", $"identifier \"{name.Text}\" evaluates to 0"));
            return 0;
            case PPExpression.Unary unary: {
                long value = Evaluate(unary.Operand, diagnostics);
                return unary.Op switch {
                    "+" => value, "-" => -value, "!" => value == 0 ? 1 : 0, _ => -value - 1
                };
            }
            case PPExpression.Conditional conditional: {
                long value = Evaluate(conditional.Condition, diagnostics);
                return Evaluate(value != 0 ? conditional.Yes : conditional.No, diagnostics);
            }
            case PPExpression.Binary binary: {
                long a = Evaluate(binary.Left, diagnostics);
                if (binary.Op == "&&" && a == 0) return 0;
                if (binary.Op == "||" && a != 0) return 1;
                long b = Evaluate(binary.Right, diagnostics);
                if (binary.Op is "/" or "%" && b == 0) throw new PPError("division by zero in #if");
                return binary.Op switch {
                    "+" => a + b, "-" => a - b, "*" => a * b, "/" => a / b, "%" => a % b, "<<" => a << (int)b, ">>" => a >> (int)b, "&" => a & b, "|" => a | b, "^" => a ^ b, "&&" or "||" => b == 0 ? 0 : 1, "<" => a < b ? 1 : 0, ">" => a > b ? 1 : 0, "<=" => a <= b ? 1 : 0, ">=" => a >= b ? 1 : 0, "==" => a == b ? 1 : 0, _ => a != b ? 1 : 0
                };
            }
            default: throw new InvalidOperationException();
        }
    }
    public static (long? Value, List<(string Kind, string Message)> Diagnostics) Test(List<Token> tokens, string directive) {
        ExpressionParser parser = new(tokens);
        List<(string, string)> diagnostics = new();
        try {
            if (tokens.Count == 0) throw new PPError($"#{directive} with no expression");
            PPExpression expression = parser.Expression();
            if (parser.Index != tokens.Count) throw new PPError($"missing binary operator before \"{tokens[parser.Index].Text}\"");
            long value = Evaluate(expression, diagnostics);
            return (value, diagnostics);
        } catch (PPError error) {
            diagnostics.Add(("error", error.Reason));
            return (null, diagnostics);
        }
    }
}

using System;
using System.IO;
using System.Collections.Generic;
using System.Linq;
sealed class SourceFile {
    public List<LogicalLine> Lines {
        get;
    }
    public int PhysicalLines {
        get;
    }
    public string? GuardName {
        get;
    }
    public SourceFile(string source) {
        Lines = Lexer.Lex(source);
        PhysicalLines = source.Count(c => c == '\n');
        GuardName = IncludeManager.Guard(Lines);
    }
    public int Entered {
        get;
        set;
    } public int Skipped {
        get;
        set;
    } public int Output {
        get;
        set;
    } public int SkippedLines {
        get;
        set;
    } public bool Once {
        get;
        set;
    }
}
sealed class IncludeManager {
    public Dictionary<string, SourceFile> Files {
        get;
    } = new();
    public List<string> Order {
        get;
    } = new();
    public static string? Search(string name, bool quoted) {
        if (quoted && File.Exists("input/" + name)) return name;
        string path = "include/" + name;
        return File.Exists("input/" + path) ? path : null;
    }
    public static string? Guard(List<LogicalLine> original) {
        List<LogicalLine> lines = original.Where(line => line.Tokens.Count > 0).ToList();
        if (lines.Count == 0) return null;
        List<Token> first = lines[0].Tokens, last = lines[^1].Tokens;
        if (first.Count != 3 || first[0].Text != "#" || first[1].Text != "ifndef" || first[2].Kind != "identifier" || last.Count != 2 || last[0].Text != "#" || last[1].Text != "endif") return null;
        int depth = 0;
        for (int i = 0; i < lines.Count; i++) {
            List<Token> tokens = lines[i].Tokens;
            string directive = tokens.Count >= 2 && tokens[0].Text == "#" && tokens[1].Kind == "identifier" ? tokens[1].Text : "";
            if (depth == 1 && directive is "elif" or "elifdef" or "elifndef" or "else") return null;
            if (directive is "if" or "ifdef" or "ifndef") depth++;
            else if (directive == "endif") depth--;
            if (depth == 0 && i + 1 != lines.Count) return null;
        } return depth == 0 ? first[2].Text : null;
    }
    public SourceFile Enter(string path) {
        if (!Files.TryGetValue(path, out SourceFile? file)) {
            file = new(File.ReadAllText("input/" + path));
            Files[path] = file;
            Order.Add(path);
        } file.Entered++;
        return file;
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
sealed record Token(string Kind, string Text, int Line, bool Space, HashSet<string> Hide) {
    public Token(string kind, string text, int line, bool space) : this(kind, text, line, space, new()) {
    }
}
sealed record LogicalLine(List<Token> Tokens, int Start, int End);
static class Lexer {
    static bool Letter(char c) => c is >= 'A' and <= 'Z' or >= 'a' and <= 'z';
    static bool Digit(char c) => c is >= '0' and <= '9';
    public static (string Kind, int Length) One(string text, int start = 0, bool header = false) {
        if (start == text.Length) return ("other", 0);
        char c = text[start];
        if (header && c == '<') {
            int end = start + 1;
            while (end < text.Length && text[end] != '\n' && text[end] != '>') end++;
            if (end < text.Length && text[end] == '>') return ("header", end - start + 1);
        }
        if (Letter(c) || c == '_') {
            int n = start + 1;
            while (n < text.Length && (Letter(text[n]) || Digit(text[n]) || text[n] == '_')) n++;
            return ("identifier", n - start);
        }
        if (Digit(c) || c == '.' && start + 1 < text.Length && Digit(text[start + 1])) {
            int n = start + 1;
            while (n < text.Length) {
                if ("eEpP".Contains(text[n]) && n + 1 < text.Length && "+-".Contains(text[n + 1])) n += 2;
                else if (Letter(text[n]) || Digit(text[n]) || "_.".Contains(text[n])) n++;
                else break;
            } return ("number", n - start);
        }
        if (c is '\'' or '"') {
            int n = start + 1;
            while (n < text.Length && text[n] != '\n') {
                if (text[n] == c) return (c == '\'' ? "character" : "string", n - start + 1);
                if (text[n] == '\\' && n + 1 < text.Length && text[n + 1] != '\n') n += 2;
                else n++;
            }
        }
        foreach (string punctuator in new[] {
            "...", "<<=", ">>=", "->", "++", "--", "<<", ">>", "<=", ">=", "==", "!=", "&&", "||", "*=", "/=", "%=", "+=", "-=", "&=", "^=", "|=", "##"
        }) if (text.AsSpan(start).StartsWith(punctuator)) return ("punctuator", punctuator.Length);
        return ("[](){}.&*+-~!/%<>^|?:;=,#".Contains(c) ? "punctuator" : "other", 1);
    }
    public static string? Single(string text) {
        if (text.Length == 0 || text.StartsWith("//", StringComparison.Ordinal) || text.StartsWith("/*", StringComparison.Ordinal)) return null;
        var (kind, n) = One(text);
        return n == text.Length ? kind : null;
    }
    static bool Separator(string left, string right) => left == "/" && (right.StartsWith('/') || right.StartsWith('*')) || One(left + right).Length != left.Length;
    public static string Render(IReadOnlyList<Token> tokens, bool output = false) {
        StringBuilder text = new();
        for (int i = 0; i < tokens.Count; i++) {
            Token token = tokens[i];
            if (i > 0 && (token.Space || output && Separator(tokens[i - 1].Text, token.Text))) text.Append(' ');
            text.Append(token.Text);
        } return text.ToString();
    }
    public static List<LogicalLine> Lex(string source) {
        StringBuilder builder = new();
        List<int> physical = new();
        int i = 0, line = 1;
        while (i < source.Length) {
            if (source[i] == '\\' && i + 1 < source.Length && source[i + 1] == '\n') {
                i += 2;
                line++;
                continue;
            } builder.Append(source[i]);
            physical.Add(line);
            if (source[i] == '\n') line++;
            i++;
        }
        string text = builder.ToString();
        List<LogicalLine> result = new();
        List<Token> tokens = new();
        int start = 1;
        bool space = true;
        i = 0;
        while (i < text.Length) {
            if (text[i] == ' ') {
                i++;
                space = true;
                continue;
            }
            if (text[i] == '\n') {
                int end = physical[i];
                result.Add(new(new(tokens), start, end));
                tokens = new();
                start = end + 1;
                i++;
                space = true;
                continue;
            }
            if (text.AsSpan(i).StartsWith("//")) {
                while (i < text.Length && text[i] != '\n') i++;
                space = true;
                continue;
            }
            if (text.AsSpan(i).StartsWith("/*")) {
                i = text.IndexOf("*/", i + 2, StringComparison.Ordinal) + 2;
                space = true;
                continue;
            }
            bool header = tokens.Count == 2 && tokens[0].Text == "#" && tokens[1].Text == "include";
            var (kind, n) = One(text, i, header);
            tokens.Add(new(kind, text.Substring(i, n), physical[i], space));
            i += n;
            space = false;
        }
        if (tokens.Count > 0) result.Add(new(tokens, start, line));
        return result;
    }
}

using System;
using System.IO;
using System.Globalization;
using System.Collections.Generic;
using System.Linq;
